INSERT  IGNORE INTO `version` (`id`, `canonical_uri`, `citation`, `creator`, `ddi_usage`, `definition`, `discussion_notes`, `initial_version`, `item_type`, `language`, `last_modified`, `license`, `license_id`, `notation`, `notes`, `number`, `previous_version`, `publication_date`, `publisher`, `status`, `title`, `translate_agency`, `translate_agency_link`, `uri`, `uri_sl`, `version_changes`, `version_notes`, `vocabulary_id`, `last_status_change_date`, `creation_date`) VALUES (206,'urn:ddi:int.ddi.cv:AnalysisUnit:1.0','DDI Alliance. (2019). Analysis Unit (Version 1.0) [Controlled vocabulary]. CESSDA. urn:ddi:int.ddi.cv:AnalysisUnit:1.0. ',40,'<div> \n <font size=\"3\" face=\"Verdana\"><a href=\"http://www.ddialliance.org/Specification/DDI-Lifecycle/3.2/\">DDI 3.2</a> </font>\n</div>\n<font size=\"3\" face=\"Verdana\"> </font>\n<div> \n <font size=\"3\" face=\"Verdana\">Module Name: reusable</font> \n</div>\n<font size=\"3\" face=\"Verdana\"> </font>\n<div> \n <font size=\"3\" face=\"Verdana\">Element Name: <a href=\"http://www.ddialliance.org/Specification/DDI-Lifecycle/3.2/XMLSchema/FieldLevelDocumentation/schemas/reusable_xsd/elements/AnalysisUnit.html\">AnalysisUnit</a></font> \n</div>\n<font size=\"3\" face=\"Verdana\"> </font>\n<div> \n <font size=\"3\" face=\"Verdana\"><br /></font> \n</div>\n<font size=\"3\" face=\"Verdana\"> </font>\n<div> \n <font size=\"3\" face=\"Verdana\"><a href=\"http://www.ddialliance.org/Specification/DDI-Codebook/2.5/\">DDI 2.5</a></font> \n</div>\n<font size=\"3\" face=\"Verdana\"> </font>\n<div> \n <font size=\"3\" face=\"Verdana\">Element/Attribute Name: <a href=\"http://www.ddialliance.org/Specification/DDI-Codebook/2.1/DTD/Documentation/anlyUnitType.html\">anlyUnit@unit</a></font> \n</div>\n<font size=\"3\" face=\"Verdana\"> </font>\n<div>\n <font size=\"3\" face=\"Verdana\"> Element/Attribute Name: <a href=\"http://www.ddialliance.org/Specification/DDI-Codebook/2.1/DTD/Documentation/anlysUnitType.html\">anlysUnit</a></font> \n</div> \n<p><font size=\"4\"><span style=\"font-size:12.0pt;font-family:&quot;Calibri&quot;,sans-serif;\nmso-fareast-font-family:Calibri;mso-fareast-theme-font:minor-latin;mso-bidi-font-family:\n&quot;Times New Roman&quot;;color:#2E75B6;mso-ansi-language:EN-US;mso-fareast-language:\nFI;mso-bidi-language:AR-SA\" lang=\"EN-US\"></span></font><font size=\"4\"><span style=\"font-size:12.0pt;font-family:&quot;Calibri&quot;,sans-serif;\nmso-fareast-font-family:Calibri;mso-fareast-theme-font:minor-latin;mso-bidi-font-family:\n&quot;Times New Roman&quot;;mso-ansi-language:EN-US;mso-fareast-language:FI;mso-bidi-language:\nAR-SA\" lang=\"EN-US\"><span style=\"color:#2E75B6\"><br /></span></span></font></p> \n<!--[if gte mso 9]><xml>\n <w:WordDocument>\n  <w:View>Normal</w:View>\n  <w:Zoom>0</w:Zoom>\n  <w:TrackMoves/>\n  <w:TrackFormatting/>\n  <w:HyphenationZone>21</w:HyphenationZone>\n  <w:PunctuationKerning/>\n  <w:ValidateAgainstSchemas/>\n  <w:SaveIfXMLInvalid>false</w:SaveIfXMLInvalid>\n  <w:IgnoreMixedContent>false</w:IgnoreMixedContent>\n  <w:AlwaysShowPlaceholderText>false</w:AlwaysShowPlaceholderText>\n  <w:DoNotPromoteQF/>\n  <w:LidThemeOther>FI</w:LidThemeOther>\n  <w:LidThemeAsian>X-NONE</w:LidThemeAsian>\n  <w:LidThemeComplexScript>X-NONE</w:LidThemeComplexScript>\n  <w:Compatibility>\n   <w:BreakWrappedTables/>\n   <w:SnapToGridInCell/>\n   <w:WrapTextWithPunct/>\n   <w:UseAsianBreakRules/>\n   <w:DontGrowAutofit/>\n   <w:SplitPgBreakAndParaMark/>\n   <w:EnableOpenTypeKerning/>\n   <w:DontFlipMirrorIndents/>\n   <w:OverrideTableStyleHps/>\n  </w:Compatibility>\n  <w:BrowserLevel>MicrosoftInternetExplorer4</w:BrowserLevel>\n  <m:mathPr>\n   <m:mathFont m:val=\"Cambria Math\"/>\n   <m:brkBin m:val=\"before\"/>\n   <m:brkBinSub m:val=\"&#45;-\"/>\n   <m:smallFrac m:val=\"off\"/>\n   <m:dispDef/>\n   <m:lMargin m:val=\"0\"/>\n   <m:rMargin m:val=\"0\"/>\n   <m:defJc m:val=\"centerGroup\"/>\n   <m:wrapIndent m:val=\"1440\"/>\n   <m:intLim m:val=\"subSup\"/>\n   <m:nar